<?php
require '_header.php';$error='';$success='';$settings=$pdo->query("SELECT * FROM app_settings WHERE id=1")->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$name=trim((string)($_POST['app_name']??'My App'));$subtitle=trim((string)($_POST['subtitle']??''));$primary=trim((string)($_POST['primary_color']??'#111827'));$support=trim((string)($_POST['support_email']??''));$privacy=trim((string)($_POST['privacy_url']??''));$terms=trim((string)($_POST['terms_url']??''));if($name==='')throw new RuntimeException('App name required');if(!preg_match('/^#[0-9A-Fa-f]{6}$/',$primary))throw new RuntimeException('Invalid HEX color');if($support!==''&&!filter_var($support,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Invalid support email');$s=$pdo->prepare("UPDATE app_settings SET app_name=?,subtitle=?,primary_color=?,support_email=?,privacy_url=?,terms_url=? WHERE id=1");$s->execute([$name,$subtitle,$primary,$support,$privacy?:null,$terms?:null]);$success='Settings saved.';$settings=$pdo->query("SELECT * FROM app_settings WHERE id=1")->fetch();}catch(Throwable $e){$error=$e->getMessage();}}
?>
<h1>App Settings</h1><?php if($success):?><div class="success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?>
<div class="card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="grid"><div><label>App Name</label><input name="app_name" value="<?=e($settings['app_name']??'My App')?>"></div><div><label>Primary Color</label><input name="primary_color" value="<?=e($settings['primary_color']??'#111827')?>"></div></div><label>Home Subtitle</label><input name="subtitle" value="<?=e($settings['subtitle']??'All Your Apps, One Place')?>"><label>Support Email</label><input name="support_email" type="email" value="<?=e($settings['support_email']??'')?>"><label>Privacy URL</label><input name="privacy_url" type="url" value="<?=e($settings['privacy_url']??'')?>"><label>Terms URL</label><input name="terms_url" type="url" value="<?=e($settings['terms_url']??'')?>"><button>Save Settings</button></form></div>
